import{_ as i,o as a,c as t,a5 as e}from"./chunks/framework.Bt0SrEfo.js";const g=JSON.parse('{"title":"Git 配置提交信息","description":"","frontmatter":{},"headers":[],"relativePath":"工具/git/8-git-config.md","filePath":"工具/git/8-git-config.md","lastUpdated":1790091846000}'),n={name:"工具/git/8-git-config.md"};function h(l,s,p,r,o,k){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="git-配置提交信息" tabindex="-1">Git 配置提交信息 <a class="header-anchor" href="#git-配置提交信息" aria-label="Permalink to &quot;Git 配置提交信息&quot;">​</a></h1><blockquote><p>Git 第一次使用时，需要配置 user.name 和 user.email，否则无法提交。 本文介绍两种配置方式：<strong>项目本地</strong>（只对当前项目生效）和<strong>全局配置</strong>（对所有项目生效）。</p></blockquote><h2 id="✅-方案一-为每个项目设置本地-git-提交信息" tabindex="-1">✅ 方案一：为每个项目设置本地 Git 提交信息 <a class="header-anchor" href="#✅-方案一-为每个项目设置本地-git-提交信息" aria-label="Permalink to &quot;✅ 方案一：为每个项目设置本地 Git 提交信息&quot;">​</a></h2><p>进入项目根目录，执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的用户名&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你的邮箱@example.com&quot;</span></span></code></pre></div><p>设置会写入到当前项目的 <code>.git/config</code> 文件中，<strong>只对当前项目生效</strong>。</p><p>📍 <strong>举例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Alice Zhang&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;alice@example.com&quot;</span></span></code></pre></div><h2 id="🧪-验证设置是否生效" tabindex="-1">🧪 验证设置是否生效 <a class="header-anchor" href="#🧪-验证设置是否生效" aria-label="Permalink to &quot;🧪 验证设置是否生效&quot;">​</a></h2><p>在项目目录中运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span></span></code></pre></div><p>应该输出你刚才设置的值。</p><h2 id="✅-方案二-可选-使用全局配置" tabindex="-1">✅ 方案二（可选）：使用全局配置 <a class="header-anchor" href="#✅-方案二-可选-使用全局配置" aria-label="Permalink to &quot;✅ 方案二（可选）：使用全局配置&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;全局用户名&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;全局邮箱@example.com&quot;</span></span></code></pre></div><p>全局设置会应用于<strong>所有项目</strong>，除非该项目有自己的本地配置（本地配置优先）。</p><h2 id="💡-推荐策略" tabindex="-1">💡 推荐策略 <a class="header-anchor" href="#💡-推荐策略" aria-label="Permalink to &quot;💡 推荐策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐方案</th></tr></thead><tbody><tr><td>工作 + 个人项目混用</td><td>用<strong>全局</strong>配置个人身份，<strong>项目本地</strong>覆盖工作身份</td></tr><tr><td>只有一个项目</td><td>直接用<strong>全局</strong>配置即可</td></tr><tr><td>多平台身份切换（如 GitHub + 公司 GitLab）</td><td>每个项目<strong>本地</strong>单独配置</td></tr></tbody></table><h2 id="🔗-相关资源" tabindex="-1">🔗 相关资源 <a class="header-anchor" href="#🔗-相关资源" aria-label="Permalink to &quot;🔗 相关资源&quot;">​</a></h2><ul><li><a href="https://git-scm.com/book/zh/v2/%E8%B5%B7%E6%AD%A5-%E5%88%9D%E6%AC%A1%E8%BF%90%E8%A1%8C-Git-%E5%89%8D%E7%9A%84%E9%85%8D%E7%BD%AE" target="_blank" rel="noreferrer">Git 官方文档 - 初次配置 Git</a></li><li><a href="https://git-scm.com/book/zh/v2/%E8%87%AA%E5%AE%9A%E4%B9%89-Git-%E9%85%8D%E7%BD%AE-User" target="_blank" rel="noreferrer">Pro Git 中文版 - 配置 user</a></li></ul>`,19)])])}const c=i(n,[["render",h]]);export{g as __pageData,c as default};
